nts:none}.hud.active{opacity:1;transform:none;pointer-events:auto}.hud-score{display:flex;align-items:baseline;gap:3px}.hud-label{display:block;font-size:8px;line-height:1.2;font-weight:800;letter-spacing:1.5px;color:#7a9188}.hud-score .hud-label{position:absolute;top:9px}.hud-score strong{font:700 27px 'Space Grotesk',sans-serif;letter-spacing:-1px;margin-top:8px}.unit{font-size:10px;color:#7a9188}.hud-divider{width:1px;height:29px;background:#d7e5df}.hud-photos{display:flex;align-items:center;gap:9px}.photo-icon{font-size:24px;color:#f69d43}.hud-photos strong{display:block;font:700 18px 'Space Grotesk',sans-serif}.pause-button{margin-left:7px;width:32px;height:32px;border:0;border-radius:10px;background:#e6f4ee;color:#50756a;font-size:13px;cursor:pointer}.overlay{position:absolute;z-index:3;inset:0;display:grid;place-items:center;padding:80px 20px 70px;background:linear-gradient(90deg,rgba(244,251,242,.85),rgba(244,251,242,.32) 49%,transparent 80%);transition:opacity .28s,visibility .28s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card{width:min(440px,90vw);margin-left:clamp(0px,7vw,100px);margin-right:auto;transform:translateY(-3px)}.eyebrow{display:flex;align-items:center;gap:8px;color:#eb7558;font-size:10px;font-weight:800;letter-spacing:2px}.sparkle{font-size:17px}h1{margin:17px 0 14px;font:700 clamp(58px,8vw,91px)/.79 'Space Grotesk',sans-serif;letter-spacing:-6px;color:#16343a}h1 span{color:#f65e4d}.intro-copy{margin:22px 0 22px;color:#58716d;font-size:15px;line-height:1.7}.intro-copy b{color:#253f41}.control-hint{display:flex;align-items:center;gap:6px;color:#667e78;font-size:10px;font-weight:700}.keycap{height:23px;min-width:23px;padding:0 6px;display:grid;place-items:center;border:1px solid #cadbd1;border-radius:6px;background:#ffffffa8;color:#344f4b;font-size:10px;box-shadow:0 2px 0 #bacdc1}.control-hint i{width:1px;height:17px;background:#c4d5cc;margin:0 5px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:28px;width:202px;margin-top:26px;padding:15px 18px;border:0;border-radius:10px;background:#f45e4d;color:#fff;font:800 11px 'DM Sans',sans-serif;letter-spacing:1.4px;box-shadow:0 8px 18px #ee5b4640;cursor:pointer;transition:transform .18s,background .18s,box-shadow .18s}.primary-button span{font-size:17px;font-weight:500}.primary-button:hover{transform:translateY(-2px);background:#e84e40;box-shadow:0 12px 24px #ee5b4650}.touch-hint{display:none;margin-top:16px;color:#718781;font-size:9px;font-weight:800;letter-spacing:1.5px}.mascot-badge{position:absolute;right:clamp(8%,12vw,190px);bottom:14%;display:flex;align-items:center;gap:8px;padding:9px 14px;border:1px solid #ffffffb0;border-radius:14px;background:#fff9;box-shadow:0 7px 22px #376b581b;transform:rotate(-4deg);font-size:19px}.mascot-badge small{font-size:9px;font-weight:800;letter-spacing:1.3px;color:#526b63}.bottom-note{position:absolute;z-index:4;bottom:23px;left:0;right:0;text-align:center;color:#5a7770;font-size:9px;font-weight:800;letter-spacing:1.7px}.bottom-note span:first-child{color:#f29c4f;font-size:13px;vertical-align:-1px}.note-separator{padding:0 8px;color:#a6b8ad}.result-card{width:min(370px,90vw);padding:30px 34px 32px;border:1px solid #ffffffc9;border-radius:24px;background:#f8fcf4ed;text-align:center;box-shadow:0 24px 70px #264d4530;backdrop-filter:blur(16px);animation:pop .35s ease-out}.pause-card{width:min(355px,90vw)}@keyframes pop{from{transform:translateY(12px) scale(.97);opacity:0}to{transform:none;opacity:1}}.result-card .eyebrow{justify-content:center;margin-top:11px}.result-icon{width:52px;height:52px;margin:auto;display:grid;place-items:center;border-radius:17px;background:#ffead6;font-size:24px;color:#ee7350}.result-card h2{margin:12px 0 8px;font:700 44px/.9 'Space Grotesk',sans-serif;letter-spacing:-2px}.result-card p{color:#6e8279;font-size:13px}.result-stats{display:flex;justify-content:center;gap:40px;margin:22px auto 10px}.result-stats div{display:grid;gap:3px}.result-stats strong{font:700 30px 'Space Grotesk',sans-serif}.result-stats span{color:#8a9b91;font-size:8px;font-weight:800;letter-spacing:1.5px}.result-card .primary-button{margin:22px auto 0;width:220px}.sub-hint{margin-top:17px;color:#91a198;font-size:9px;font-weight:800;letter-spacing:1.5px}.mobile-controls{display:none;position:absolute;z-index:5;bottom:44px;left:50%;transform:translateX(-50%);align-items:center;gap:13px}.mobile-controls button{width:50px;height:50px;border:1px solid #ffffffb8;border-radius:16px;background:#ffffffb8;color:#34544c;font-size:30px;line-height:1;box-shadow:0 7px 16px #31554a18;touch-action:manipulation}.mobile-controls .jump-control{background:#f45e4d;color:white;font-size:22px;font-weight:700}.toast{position:absolute;z-index:6;left:50%;top:24%;transform:translate(-50%,-8px);padding:10px 17px;border-radius:30px;background:#183c3bdc;color:white;font-size:10px;font-weight:800;letter-spacing:1.3px;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
